#!/bin/sh
set -eu

# Run inside the built frontend image to verify the documents generated by the SEO build.
response=$(mktemp)
trap 'rm -f "$response"' EXIT

for attempt in 1 2 3 4 5; do
    if wget -q -O "$response" http://127.0.0.1/healthz; then
        break
    fi
    sleep 1
done

for route in / /problems /problems/rating /problems/study-plans /projects /tests /contests /contests/rating /challenges /challenges/rating /duels /duels/rating /arena /tournaments /hackathons /blog /users /calendar /games /kepcoin /shop; do
    wget -q -O "$response" "http://127.0.0.1$route"
    cmp "$response" "/usr/share/nginx/html${route%/}/index.html"
    printf 'SEO document OK: %s\n' "$route"
done

for route in /games/world /games/keppy-world /games/code-islands /games/bug-hunt /games/logic-circuit /games/memory-grid /problems/2349 /contests/502/standings /hackathons/3/projects/A /duels/320 /users/admin /settings/teams /admin/problems '/contests?page=2' '/problems?difficulty=3'; do
    wget -q -O "$response" "http://127.0.0.1$route"
    cmp "$response" /usr/share/nginx/html/app.html
    printf 'SPA fallback OK: %s\n' "$route"
done

wget -q -O "$response" http://127.0.0.1/games/
cmp "$response" /usr/share/nginx/html/games/index.html
printf 'SEO directory route OK\n'

wget -S -O /dev/null http://127.0.0.1/games/world 2>&1 | grep -iq 'Cache-Control: no-cache, must-revalidate'
printf 'SPA document cache policy OK\n'

wget -S -O /dev/null http://127.0.0.1/settings/teams 2>&1 | grep -iq 'X-Robots-Tag: noindex, follow'
printf 'Private route indexing policy OK\n'

wget -q -O "$response" http://127.0.0.1/games/bug-hunt-preview.svg
cmp "$response" /usr/share/nginx/html/games/bug-hunt-preview.svg
printf 'Static game asset OK\n'
